const std=@import("std");const X=@import("experimental/hydration_exchange_quantum.zig");const B=@import("experimental/hydration_exchange.zig");const M=X.M;const W=@import("water_brush.zig");const area:f64=7669529600;
fn cell()M.Cell{var c=M.initialized(123);c.cohorts[0]=.{.biomass=0.0083355103,.support_mass=9.616019e-5,.organization=0.016675837,.lineage=2003,.retention_allocation=0.03125};return c;}
fn env()M.Environment{return .{.temperature=300,.depth_km=0,.light=0,.carbon_available=0,.oxygen_carbon_capacity=0};}
test "actual-capacity endpoint receipt and repeated closed water cycles"{var c=cell();var l:f32=3101.661865234375;var v:f32=0;const initial=X.total(c,l,v,area);var maxerr:f64=0;var peak:f64=0;for(0..1000)|_|{_=X.step(&c,&l,&v,area,env(),60).?;maxerr=@max(maxerr,@abs(X.total(c,l,v,area)-initial));peak=@max(peak,c.liquid_return);try std.testing.expect(maxerr<=1e-9);}std.debug.print("QUANTUM_CYCLES maxerr={d} peak_nonhydrating={d} final_store={d}\n",.{maxerr,peak,c.cohorts[0].stored_water});}
test "actual Water minus preserves accounting and can return loose remainder"{var c=cell();var l=[_]f32{3101.661865234375};var v:f32=0;_=X.step(&c,&l[0],&v,area,env(),0.001).?;const before=X.total(c,l[0],v,area);const old=l[0];const escrow=c.liquid_return;const result=W.remove(&l,0,@floatCast((1e9/area)/1e6),true,0);try std.testing.expect(result.status==.changed);const removed=(@as(f64,old)-l[0])*(1e9/area);const after_edit=l[0];_=X.step(&c,&l[0],&v,area,env(),0.001).?;try std.testing.expect(@abs(X.total(c,l[0],v,area)+removed-before)<=1e-9);std.debug.print("QUANTUM_DRAIN escrow_before={d} physical_after_edit={d} after_exchange={d} remaining_escrow={d}\n",.{escrow,after_edit,l[0],c.liquid_return});}
test "zero retention remains exact across 1000 coupled adapter steps"{var c=cell();c.cohorts[0].retention_allocation=0;var b=c;var l:f32=3101.6619;var bl=l;var v:f32=0;var bv=v;for(0..1000)|_|{const xf=X.step(&c,&l,&v,area,env(),60).?;const bf=B.step(&b,&bl,&bv,area,env(),60).?;try std.testing.expectEqualDeep(b,c);try std.testing.expectEqualDeep(bf,xf);try std.testing.expectEqual(bl,l);try std.testing.expectEqual(bv,v);}}
test "derived overflow refuses before state change"{var c=cell();const old=c;var l:f32=1;var v:f32=0;try std.testing.expect(X.step(&c,&l,&v,1e-250,env(),60)==null);try std.testing.expectEqualDeep(old,c);try std.testing.expectEqual(@as(f32,1),l);}
